entries[413091] = { ["name"] = "Heilige Nova", ["text"] = "275 Mana\nWirken in 2 sek.\nVerursacht eine Explosion heiligen Lichts um den Zaubernden herum und fügt allen gegnerischen Zielen in einem Umkreis von 10 Metern 1080 to 1320 Heiligschaden zu. Zusätzlich werden alle Gruppenmitglieder in einem Umkreis von 10 Metern um 360 to 440 Gesundheit geheilt. Dieser Effekt erzeugt keine Bedrohung." }
